export default "<template>\n  <div>\n    <raw-loader v-show=\"level == 9\" :mytxt=\"require('!raw-loader!./TestModalBase.vue').default\"\n        :btnText=\"`Code TestModalBase [${level}]`\"></raw-loader>\n    <h4>This is Tpl</h4>\n    level : {{ level }}<br>\n    <button @click=\"onAdd()\">Add</button>\n    <ul>\n      <li v-for=\" x in hss \" :key=\"x.Id\">\n        {{ x }}\n        <button @click=\"onEdit(x)\">Edit</button>\n      </li>\n    </ul>\n    <ModalBase\n        title=\"Modal Base\" \n        size=\"md\" \n        ref=\"modal\" \n        v-model=\"obj\" \n        :listFields=\"[\n          { key: 'Id', label: 'ID' },\n          { key: 'Ten', label: 'Tên' },\n          // { key: 'Ngay', label: 'Ngày' },\n          // { key: 'Tien', label: 'Tiền' },\n          // { key: 'Loai', label: 'Loại' },\n        ]\" \n        @save=\"onSave\"\n    >\n      <!-- <BTableNhatKy2\n        :MonQuyCachs=\"getMonQuyCachCombo()\"\n        :PhieuNXId=\"obj_phieu_nhap_xuat.Id\"\n        v-model=\"ct\"\n        ref=\"ct\"\n      ></BTableNhatKy2> -->\n    </ModalBase>  \n\n  </div>\n</template>\n\n<script>\nimport ModalBase from './Com/ModalBase.vue';\n\n\nexport default {\n  name: 'HomeView',\n  components: {\n    ModalBase\n  },\n  computed: {\n    user() {\n      return JSON.parse(localStorage.getItem('user') || '{}')\n    },\n    level() {\n      return this.user.level || 0\n    }\n  },\n  mounted(){\n    //this.$refs.modal.open();\n  },\n  data(){\n    return{\n      obj:{},\n      hss:[\n        {Id:1,Ten:'Thuc 101'},\n      ]\n    }\n  },\n  methods:{\n    onSave(){\n      let x = {...this.obj};\n      if(x.Id==0){\n        x.Id=new Date().getTime();\n        this.hss.push(x);\n      }else{\n        let obj=this.hss.find(a=>a.Id==x.Id);\n        if(obj){\n          obj.Ten=x.Ten;\n        }\n      }\n      this.$refs.modal.close()\n\n    },\n    onEdit(x){\n      this.obj={...x};\n      this.$refs.modal.open();\n    },\n    onAdd(){\n      this.obj={\n        Id:0,\n        Ten:'thuc xxxx'\n      };\n      this.$refs.modal.open();\n    }\n\n  },\n\n\n}\n</script>\n";